std::map<std::string, int> wordCount(const std::string& text) {
    std::map<std::string, int> counts;
    std::string word;
    for (char c : text) {
        if (c == ' ') {
            if (!word.empty()) {
                counts[word]++;
                word.clear();
            }
        } else {
            word += c;
        }
    }
    if (!word.empty()) counts[word]++;
    return counts;
}
